// src/components/TokenFaucet.jsx
import React, { useState, useEffect } from 'react';
import { Web3Provider } from '@ethersproject/providers';
import { ethers } from 'ethers';

const contractAddress = "0x992b58ecb6203698e3615e1ad4343a1227e12ea9";
const contractABI = [
    "function faucet() public",
    "function faucetAmount() public view returns (uint256)",
    "function cooldownTime() public view returns (uint256)",
    "function lastClaimed(address) public view returns (uint256)"
];

const TokenFaucet = () => {
    const [isConnected, setIsConnected] = useState(false);
    const [statusMessage, setStatusMessage] = useState("Conecta tu billetera para reclamar tokens.");
    const [provider, setProvider] = useState(null);
    const [signer, setSigner] = useState(null);
    const [contract, setContract] = useState(null);
    const [cooldownTime, setCooldownTime] = useState(0);
    const [lastClaimed, setLastClaimed] = useState(0);
    const [canClaim, setCanClaim] = useState(true);

    const connectWallet = async () => {
        if (window.ethereum) {
            try {
                const tempProvider = new Web3Provider(window.ethereum);
                await tempProvider.send("eth_requestAccounts", []);
                const tempSigner = tempProvider.getSigner();
                const tempContract = new ethers.Contract(contractAddress, contractABI, tempSigner);

                setProvider(tempProvider);
                setSigner(tempSigner);
                setContract(tempContract);
                setIsConnected(true);
                setStatusMessage("Conectado con MetaMask. Ahora puedes reclamar tokens.");

                // Obtener tiempo de espera (cooldown) y última reclamación del usuario
                let cooldown = await tempContract.cooldownTime();
                let lastClaim = await tempContract.lastClaimed(await tempSigner.getAddress());

                // Convertir a número si es necesario (verificar si es un BigNumber)
                if (cooldown._isBigNumber) cooldown = cooldown.toNumber();
                if (lastClaim._isBigNumber) lastClaim = lastClaim.toNumber();

                setCooldownTime(cooldown);
                setLastClaimed(lastClaim);
            } catch (error) {
                console.error("Error al conectar MetaMask:", error);
                setStatusMessage("Error al conectar MetaMask.");
            }
        } else {
            setStatusMessage("MetaMask no está instalado. Por favor instala MetaMask.");
        }
    };

    useEffect(() => {
        if (lastClaimed && cooldownTime) {
            const nextClaimTime = lastClaimed + cooldownTime;
            const currentTime = Math.floor(Date.now() / 1000); // Tiempo actual en segundos
            setCanClaim(currentTime >= nextClaimTime);
            if (!canClaim) {
                const remainingTime = nextClaimTime - currentTime;
                setStatusMessage(`Debes esperar ${Math.ceil(remainingTime / 60)} minutos para reclamar nuevamente.`);
            }
        }
    }, [lastClaimed, cooldownTime, canClaim]);

    const claimTokens = async () => {
        if (!contract) return;
        try {
            setStatusMessage("Procesando transacción...");
            const transaction = await contract.faucet();
            await transaction.wait();

            // Actualizar el tiempo de la última reclamación
            const newLastClaim = await contract.lastClaimed(await signer.getAddress());
            setLastClaimed(newLastClaim.toNumber());

            setStatusMessage("Tokens Sent Successfully.");
        } catch (error) {
            console.error("Error al reclamar tokens:", error);
            setStatusMessage("Error al reclamar tokens.");
        }
    };

    return (
        <div className="bg-gray-800 text-white p-6 rounded-lg shadow-lg max-w-md mx-auto text-center space-y-6">
            <h2 className="text-3xl font-semibold text-indigo-400 mb-2">Faucet de ArchToken</h2>
            <p className="text-gray-300">{statusMessage}</p>
            <button
                onClick={connectWallet}
                disabled={isConnected}
                className={`w-full bg-indigo-600 hover:bg-indigo-700 text-white font-semibold py-3 px-4 rounded-lg transition duration-300 ${isConnected ? 'opacity-50 cursor-not-allowed' : ''}`}
            >
                {isConnected ? "Conectado" : "Conectar MetaMask"}
            </button>
            <button
                onClick={claimTokens}
                disabled={!isConnected || !canClaim}
                className={`w-full bg-green-500 hover:bg-green-600 text-white font-semibold py-3 px-4 rounded-lg transition duration-300 ${(!isConnected || !canClaim) ? 'opacity-50 cursor-not-allowed' : ''}`}
            >
                Reclamar Tokens
            </button>
        </div>
    );
};

export default TokenFaucet;
